html:
{% if letter_head %}{{ letter_head }}{% endif %}

<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body, .po-wrap {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10pt;
    color: #1a1a1a;
    background: #fff;
  }

  @media print {
    .po-wrap { width: 100%; }
    .no-break { page-break-inside: avoid; }
  }

  .po-wrap {
    width: 100%;
    max-width: 780px;
    margin: 0 auto;
  }

  /* ── HEADER ── */
  .po-hdr {
    width: 100%;
    border-collapse: collapse;
    border-bottom: 3px solid #7b2fbf;
    padding-bottom: 12px;
    margin-bottom: 14px;
  }
  .po-hdr-left {
    vertical-align: top;
    width: 50%;
  }
  .po-hdr-right {
    vertical-align: top;
    text-align: right;
    width: 50%;
  }
  .po-brand {
    font-size: 18pt;
    font-weight: bold;
    color: #7b2fbf;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
  .po-brand-sub {
    font-size: 9pt;
    color: #555;
    margin-top: 4px;
    line-height: 1.6;
  }
  .po-title-badge {
    font-size: 22pt;
    font-weight: bold;
    color: #f0e6ff;
    text-transform: uppercase;
    letter-spacing: 3px;
    background: #7b2fbf;
    padding: 4px 14px;
    display: inline-block;
  }
  .po-doc-id {
    font-size: 8.5pt;
    color: #aaa;
    margin-top: 5px;
  }
  .po-status {
    display: inline-block;
    font-size: 8pt;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 2px 8px;
    border-radius: 3px;
    margin-top: 6px;
  }
  .po-status-draft { background: #fff3cd; color: #856404; }
  .po-status-submitted { background: #d4edda; color: #155724; }
  .po-status-cancelled { background: #f8d7da; color: #721c24; }

  /* ── META BAR ── */
  .po-meta {
    width: 100%;
    border-collapse: collapse;
    background: #faf5ff;
    border: 1px solid #e4d4f7;
    margin-bottom: 16px;
  }
  .po-meta td {
    padding: 10px 14px;
    vertical-align: top;
    border-right: 1px solid #e4d4f7;
  }
  .po-meta td:last-child { border-right: none; }
  .po-label {
    font-size: 7pt;
    font-weight: bold;
    color: #7b2fbf;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 3px;
  }
  .po-value {
    font-size: 10pt;
    font-weight: bold;
    color: #1a1a1a;
  }
  .po-sub {
    font-size: 8.5pt;
    color: #666;
    margin-top: 1px;
  }

  /* ── INFO CARDS ── */
  .po-cards {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
  }
  .po-card {
    vertical-align: top;
    width: 50%;
    padding: 0;
  }
  .po-card:first-child { padding-right: 8px; }
  .po-card:last-child { padding-left: 8px; }
  .po-card-inner {
    border: 1px solid #e4d4f7;
    border-left: 4px solid #7b2fbf;
    background: #faf5ff;
    padding: 11px 14px;
    font-size: 9pt;
    line-height: 1.8;
  }
  .po-card-title {
    font-size: 7.5pt;
    font-weight: bold;
    color: #7b2fbf;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding-bottom: 5px;
    border-bottom: 1px solid #e4d4f7;
    margin-bottom: 6px;
  }
  .po-card-row {
    width: 100%;
    border-collapse: collapse;
  }
  .po-card-row td { padding: 1px 0; font-size: 9pt; }
  .po-card-lbl { color: #888; font-size: 8.5pt; width: 40%; }
  .po-card-val { font-weight: bold; color: #1a1a1a; }

  /* ── ADDRESS BOX ── */
  .po-address {
    border: 1px solid #e4d4f7;
    background: #faf5ff;
    padding: 10px 14px;
    margin-bottom: 16px;
    font-size: 9pt;
    line-height: 1.6;
  }

  /* ── ITEMS TABLE ── */
  .po-items {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    font-size: 9.5pt;
  }
  .po-items thead tr { background: #7b2fbf; color: #fff; }
  .po-items thead th {
    padding: 7px 8px;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 7.5pt;
    letter-spacing: 0.5px;
    border: none;
  }
  .po-items tbody tr:nth-child(even) { background: #faf5ff; }
  .po-items tbody tr:nth-child(odd)  { background: #fff; }
  .po-items tbody td {
    padding: 7px 8px;
    border-bottom: 1px solid #eeddf7;
    vertical-align: middle;
  }
  .po-items tfoot tr { background: #f0e6ff; }
  .po-items tfoot td {
    padding: 7px 8px;
    font-weight: bold;
    border-top: 2px solid #7b2fbf;
  }

  /* ── TOTALS BOX ── */
  .po-totals-wrap {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
  }
  .po-totals-spacer { width: 55%; }
  .po-totals-box { width: 45%; vertical-align: top; }
  .po-totals-inner {
    width: 100%;
    border-collapse: collapse;
  }
  .po-totals-inner td {
    padding: 5px 8px;
    border-bottom: 1px solid #f0e6ff;
    font-size: 10pt;
  }
  .po-totals-lbl { color: #555; font-size: 9.5pt; text-align: left; }
  .po-totals-val { font-weight: bold; color: #1a1a1a; text-align: right; }
  .po-grand-row td {
    background: #7b2fbf;
    color: #fff;
    font-size: 11pt;
    font-weight: bold;
    padding: 8px 10px;
    border-bottom: none;
  }

  /* ── NOTES ── */
  .po-notes {
    margin-top: 8px;
    padding: 10px 14px;
    border: 1px solid #e4d4f7;
    background: #faf5ff;
    font-size: 9pt;
    color: #444;
    line-height: 1.6;
  }
  .po-notes-title {
    font-size: 7.5pt;
    font-weight: bold;
    color: #7b2fbf;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 4px;
  }

  /* ── FOOTER ── */
  .po-footer {
    margin-top: 24px;
    padding-top: 12px;
    border-top: 2px solid #e4d4f7;
    text-align: center;
    font-size: 8pt;
    color: #999;
    line-height: 1.8;
  }
  .po-footer strong { color: #7b2fbf; }
</style>

<div class="po-wrap">

  <!-- ══ HEADER ══ -->
  <table class="po-hdr" cellpadding="0" cellspacing="0">
    <tr>
      <td class="po-hdr-left">
        <div class="po-brand">MOTLEY TERPZ, LLC</div>
        <div class="po-brand-sub">
          California<br>
          310-780-4784
        </div>
      </td>
      <td class="po-hdr-right">
        <div class="po-title-badge">Pre-Order</div>
        <div class="po-doc-id">{{ doc.name }}</div>
        {% if doc.docstatus == 0 %}
          <div class="po-status po-status-draft">Draft</div>
        {% elif doc.docstatus == 1 %}
          <div class="po-status po-status-submitted">Submitted</div>
        {% elif doc.docstatus == 2 %}
          <div class="po-status po-status-cancelled">Cancelled</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <!-- ══ META BAR ══ -->
  <table class="po-meta" cellpadding="0" cellspacing="0">
    <tr>
      <td style="width:30%;">
        <div class="po-label">Brand</div>
        <div class="po-value">{{ doc.brand_name or '&mdash;' }}</div>
        {% if doc.company %}<div class="po-sub">{{ doc.company }}</div>{% endif %}
      </td>
      <td style="width:20%;">
        <div class="po-label">Order Date</div>
        <div class="po-value">{{ frappe.format_date(doc.order_date) if doc.order_date else '&mdash;' }}</div>
      </td>
      <td style="width:25%;">
        <div class="po-label">Requested Delivery</div>
        <div class="po-value">{{ frappe.format_date(doc.requested_delivery_date) if doc.requested_delivery_date else '&mdash;' }}</div>
      </td>
      <td style="width:25%; text-align:right;">
        <div class="po-label">Region</div>
        <div class="po-value" style="color:#7b2fbf;">{{ doc.region or '&mdash;' }}</div>
      </td>
    </tr>
  </table>

  <!-- ══ REP + LICENSE CARDS ══ -->
  <table class="po-cards" cellpadding="0" cellspacing="0">
    <tr>
      <td class="po-card">
        <div class="po-card-inner">
          <div class="po-card-title">Sales Rep</div>
          <table class="po-card-row" cellpadding="0" cellspacing="0">
            <tr>
              <td class="po-card-lbl">Name</td>
              <td class="po-card-val">{{ doc.rep_name or '&mdash;' }}</td>
            </tr>
            <tr>
              <td class="po-card-lbl">Email</td>
              <td class="po-card-val">{{ doc.rep_email or '&mdash;' }}</td>
            </tr>
            <tr>
              <td class="po-card-lbl">Phone</td>
              <td class="po-card-val">{{ doc.rep_phone or '&mdash;' }}</td>
            </tr>
          </table>
        </div>
      </td>
      <td class="po-card">
        <div class="po-card-inner">
          <div class="po-card-title">License Information</div>
          <table class="po-card-row" cellpadding="0" cellspacing="0">
            <tr>
              <td class="po-card-lbl">License Name</td>
              <td class="po-card-val">{{ doc.license_name or '&mdash;' }}</td>
            </tr>
            <tr>
              <td class="po-card-lbl">License #</td>
              <td class="po-card-val">{{ doc.license_number or '&mdash;' }}</td>
            </tr>
          </table>
        </div>
      </td>
    </tr>
  </table>

  <!-- ══ ADDRESS ══ -->
  {% if doc.primary_address %}
  <div class="po-address no-break">
    <div class="po-label">Primary Address</div>
    <div style="margin-top:4px; white-space:pre-line;">{{ doc.primary_address }}</div>
  </div>
  {% endif %}

  <!-- ══ ITEMS TABLE ══ -->
  {% set totals = { 'qty': 0, 'amount': 0 } %}
  <table class="po-items no-break" cellpadding="0" cellspacing="0">
    <thead>
      <tr>
        <th style="width:4%; text-align:center;">#</th>
        <th style="width:16%; text-align:left;">Item Code</th>
        <th style="width:22%; text-align:left;">Item Name</th>
        <th style="width:14%; text-align:center;">Group</th>
        <th style="width:8%; text-align:center;">Qty</th>
        <th style="width:8%; text-align:center;">UOM</th>
        <th style="width:14%; text-align:right;">Rate</th>
        <th style="width:14%; text-align:right;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      {% set _ = totals.update({'qty': totals.qty + (item.qty or 0), 'amount': totals.amount + (item.amount or 0)}) %}
      <tr>
        <td style="text-align:center; color:#bbb;">{{ loop.index }}</td>
        <td>{{ item.item_code or '' }}</td>
        <td><strong>{{ item.item_name or '' }}</strong></td>
        <td style="text-align:center; color:#7b2fbf; font-size:8pt;">{{ item.item_group or '' }}</td>
        <td style="text-align:center; font-weight:bold;">{{ item.qty or 0 }}</td>
        <td style="text-align:center;">{{ item.uom or '' }}</td>
        <td style="text-align:right;">{{ frappe.utils.fmt_money(item.rate, currency='USD') if item.rate else '' }}</td>
        <td style="text-align:right; font-weight:bold;">{{ frappe.utils.fmt_money(item.amount, currency='USD') if item.amount else '' }}</td>
      </tr>
      {% endfor %}
      {% if not doc.items %}
      <tr>
        <td colspan="8" style="text-align:center; color:#aaa; padding:16px;">No items added</td>
      </tr>
      {% endif %}
    </tbody>
    {% if doc.items %}
    <tfoot>
      <tr>
        <td colspan="4" style="text-align:right;">Totals</td>
        <td style="text-align:center;">{{ totals.qty }}</td>
        <td></td>
        <td></td>
        <td style="text-align:right;">{{ frappe.utils.fmt_money(totals.amount, currency='USD') if totals.amount else '' }}</td>
      </tr>
    </tfoot>
    {% endif %}
  </table>

  <!-- ══ TOTALS BOX ══ -->
  {% if doc.items and totals.amount %}
  <table class="po-totals-wrap" cellpadding="0" cellspacing="0">
    <tr>
      <td class="po-totals-spacer"></td>
      <td class="po-totals-box">
        <table class="po-totals-inner" cellpadding="0" cellspacing="0">
          <tr>
            <td class="po-totals-lbl">Total SKUs</td>
            <td class="po-totals-val">{{ doc.items | length }}</td>
          </tr>
          <tr>
            <td class="po-totals-lbl">Total Qty</td>
            <td class="po-totals-val">{{ totals.qty }}</td>
          </tr>
          <tr class="po-grand-row">
            <td>Grand Total</td>
            <td style="text-align:right;">{{ frappe.utils.fmt_money(totals.amount, currency='USD') }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
  {% endif %}

  <!-- ══ ITEM NOTES ══ -->
  {% set has_item_notes = [] %}
  {% for item in doc.items %}
    {% if item.notes %}{% set _ = has_item_notes.append(item) %}{% endif %}
  {% endfor %}
  {% if has_item_notes %}
  <div class="po-notes no-break">
    <div class="po-notes-title">Item Notes</div>
    {% for item in has_item_notes %}
    <div style="margin-bottom:4px;"><strong>{{ item.item_code or item.item_name }}:</strong> {{ item.notes }}</div>
    {% endfor %}
  </div>
  {% endif %}

  <!-- ══ ORDER NOTES ══ -->
  {% if doc.notes %}
  <div class="po-notes no-break" style="margin-top:12px;">
    <div class="po-notes-title">Order Notes</div>
    {{ doc.notes }}
  </div>
  {% endif %}

  <!-- ══ FOOTER ══ -->
  <div class="po-footer no-break">
    <strong>MOTLEY TERPZ, LLC</strong> &mdash; Pre-Order Confirmation<br>
    This document is a pre-order record and does not constitute a binding sales agreement.<br>
    For questions, contact your sales representative.
  </div>

</div>
